import{_ as a,c as s,o as r,ae as i}from"./chunks/framework.DI6M9D4h.js";const n="/assets/required-tools-1.B-wsgol0.jpg",l="/assets/soldering-hints-1.BB-Z7lJd.png",h="/assets/soldering-hints-3.CR6kALtT.jpg",d="/assets/soldering-hints-2.C_bJUhZe.png",c="/assets/kimiko-parts-1.Cf-rLB5V.jpg",p="/assets/smd-diode-direction-1.5pqq2ES9.png",m="/assets/smd-diode-solder-1.DQkcFRwe.jpg",g="/assets/smd-diode-solder-2.DZ9VG5jU.jpg",u="/assets/smd-diode-solder-3.DLMvKFNF.jpg",f="/assets/sk6812-mini-e-led-1.DhVxsMs4.jpg",k="/assets/sk6812-mini-e-led-2.DFwUScdr.jpg",b="/assets/sk6812-mini-e-led-3.CHnZHjWe.jpg",y="/assets/trrs-jack-reset-button-1.CmgnjwsP.jpg",w="/assets/oled-jumper-pins-1.bsw_vUMx.jpg",_="/assets/puchi-c-working-test-1.oPC3SeOs.jpg",P="/assets/mill-max-12-single-row-socket-1.D5msQrQ_.jpg",t="/assets/mill-max-12-single-row-socket-6.MwqXZoiQ.jpg",o="/assets/pro-micro-solder-location-1.Cm_hMVMg.jpg",q="/assets/mill-max-12-single-row-socket-5.CITOG5kf.jpg",M="/assets/pro-micro-tape-diode-legs-1.DyBjswHU.jpg",x="/assets/mill-max-12-single-row-socket-2.DTKvaXum.jpg",S="/assets/mill-max-12-single-row-socket-3.epvkCPen.jpg",C="/assets/mill-max-12-single-row-socket-4.LxhGq6ih.jpg",v="/assets/pro-micro-wedgin-1.yEquoB_F.jpg",T="/assets/oled-shorten-pins-sd1306-1.C2mS6CEG.jpg",B="/assets/oled-shorten-pins-sd1306-2.ud7S4nZ4.jpg",D="/assets/kailh-socket-pad-test-1.CosxyQk7.jpg",j="/assets/solder-kailh-mx-sockets-1.CPYT5jrw.jpg",z="/assets/solder-kailh-mx-sockets-2.CJOBIqNQ.jpg",R="/assets/case-all-parts-1.DfCSs8pZ.jpg",E="/assets/case-spacer-guard-plate-1.C1GsnIaT.jpg",I="/assets/case-top-plate-spacer-1.CkFz0Q3i.jpg",L="/assets/case-top-plate-washer-1.Ci7I9iFX.jpg",A="/assets/rotary-encoder-cut-legs-1.CVc4bpRX.jpg",O="/assets/rotary-encoder-isolation-tape-1.BGCoMnaI.jpg",K="/assets/rotary-encoder-position-1.DosqjPHU.jpg",U="/assets/rotary-encoder-position-2.Cf9PVLPE.jpg",Q="/assets/case-top-plate-spacer-switches.BvzaftPr.jpg",F="/assets/switch-pins-align-1.BKQ8GpVM.jpg",G="/assets/case-top-plate-align-2.BHuTL-tx.jpg",H="/assets/case-top-plate-align-1.OPLTKfEw.jpg",Y="/assets/case-top-plate-complete-1.V_BoEEQ6.jpg",N="/assets/rotary-encoder-solder-1.CPEda_04.jpg",Z="/assets/guard-plate-2.BC94ZapK.jpg",V="/assets/guard-plate-3.ChbnORsQ.jpg",W="/assets/guard-plate-1.BIWmY3oa.jpg",X="/assets/case-bottom-plate-1.CqBfovEg.jpg",ie=JSON.parse('{"title":"Kimiko Build Guide","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/kimiko/index.md","filePath":"build-guides/kimiko/index.md","lastUpdated":1767696877000}'),J={name:"build-guides/kimiko/index.md"};function $(ee,e,te,oe,ae,se){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="kimiko-build-guide" tabindex="-1">Kimiko Build Guide <a class="header-anchor" href="#kimiko-build-guide" aria-label="Permalink to &quot;Kimiko Build Guide&quot;">​</a></h1><p><a href="https://github.com/firstcontributions/first-contributions" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/PRs-welcome-brightgreen.svg?style=flat-square" alt="PRs Welcome" loading="lazy"></a><a href="https://discord.gg/frjFXZB" title="Redirect to Keycapsss Discord" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/548530462419582996?style=flat-square&amp;logo=discord&amp;logoColor=white" alt="Discord" loading="lazy"></a><a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/License-CC%20BY--NC--SA%204.0-lightgrey.svg?style=flat-square" alt="License: CC BY-NC-SA 4.0" loading="lazy"></a></p><h2 id="required-tools" tabindex="-1">Required tools <a class="header-anchor" href="#required-tools" aria-label="Permalink to &quot;Required tools&quot;">​</a></h2><p><img src="'+n+'" alt="Required tools for soldering" loading="lazy"></p><ul><li>Soldering iron with adjustable temperature</li><li>Solder (i use Sn99.3Cu0.7 0.5mm/0.02inch)</li><li>Tweezers for the small SMD parts</li><li>Tip cleaner (wet sponge or brass wool)</li><li>Side cutters/flush cutters</li><li>Fine pliers</li></ul><p>Most parts I solder at 320-340°C. The SMD LEDs are temperature sensitive, so lower the temperature to 300-320°C.</p><h3 id="how-to-solder-tips" tabindex="-1">How to solder tips <a class="header-anchor" href="#how-to-solder-tips" aria-label="Permalink to &quot;How to solder tips&quot;">​</a></h3><p><img src="'+l+'" alt="How to THT soldering" loading="lazy"><em><a href="https://github.com/adafruit/Reference-Cards" target="_blank" rel="noreferrer">adafruit</a> CC-BY-SA 4.0</em></p><p><img src="'+h+'" alt="How to THT soldering" loading="lazy"><em>Source: <a href="https://learn.adafruit.com/adafruit-guide-excellent-soldering/common-problems" target="_blank" rel="noreferrer">adafruit</a></em></p><p><img src="'+d+'" alt="How to SMD soldering" loading="lazy"><em><a href="https://github.com/marove2000/referenceCards" target="_blank" rel="noreferrer">Timo Schindler</a> CC-BY-SA 4.0</em></p><h2 id="bom" tabindex="-1">BOM <a class="header-anchor" href="#bom" aria-label="Permalink to &quot;BOM&quot;">​</a></h2><p><img src="'+c+'" alt="Kimiko Parts" loading="lazy"></p><h3 id="required-parts" tabindex="-1">Required parts <a class="header-anchor" href="#required-parts" aria-label="Permalink to &quot;Required parts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Part name</th><th>Quantity</th><th>Remarks</th><th>Photo</th></tr></thead><tbody><tr><td>Kimiko PCB</td><td>2 pcs</td><td>PCB is reversible</td><td></td></tr><tr><td>Kimiko case</td><td>1 set</td><td>2 solid panels, 2 plates, and screws/spacer</td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/79/arduino-pro-micro-atmega32u4-controller" target="_blank" rel="noreferrer">Pro Micro</a> or <a href="https://keycapsss.com/keyboard-parts/parts/141/Puchi-C-pro-micro-replacement-with-usb-c-and-atmega32u4" target="_blank" rel="noreferrer">Puchi-C</a></td><td>2 pcs (a mix is possible)</td><td>I highly recommend, use <a href="https://keycapsss.com/keyboard-parts/parts/100/single-row-socket-headers-pins-mill-max-series-315" target="_blank" rel="noreferrer">Mill-Max Single Row Socket Headers</a>, or <a href="https://keycapsss.com/keyboard-parts/parts/91/spring-loaded-pin-headers-12-pin-2pcs-conthrough" target="_blank" rel="noreferrer">Spring-loaded pin headers</a>, to make it Hot-swappable.</td><td></td></tr><tr><td>Key switch (MX)</td><td>58-60 pcs</td><td>60 if you do not install the rotary encoder. 3-Pin and 5-Pin switches are supported.</td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/49/kailh-hot-swap-pcb-sockets-10-pcs" target="_blank" rel="noreferrer">Kailh MX switch socket</a></td><td>58-60 pcs</td><td></td><td></td></tr><tr><td>Diodes 1N4148W (SMD SOD-123/SOD-123FL)</td><td>60 pcs</td><td></td><td></td></tr><tr><td>TRRS jack</td><td>2 pcs</td><td></td><td></td></tr><tr><td>Tactile switch</td><td>2 pcs</td><td>Reset switch</td><td></td></tr><tr><td>TRRS cable</td><td>1 cable</td><td>Must be a 4-pole cable</td><td></td></tr><tr><td>Key caps</td><td>58-60 pcs</td><td>Keycap for the thumb switch can be a 1.5U, or a 1U keycap.</td><td></td></tr><tr><td>Micro USB or USB-C cable</td><td>1 pcs</td><td>Dependent what you use on the master half (Pro Micro = Micro USB / Puchi-C = USB-C).</td><td></td></tr></tbody></table><h3 id="optionally-parts" tabindex="-1">Optionally parts <a class="header-anchor" href="#optionally-parts" aria-label="Permalink to &quot;Optionally parts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Part name</th><th>Quantity</th><th>Remarks</th><th>Photo</th></tr></thead><tbody><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/59/rotary-encoder-with-switch" target="_blank" rel="noreferrer">Rotary encoder</a></td><td>0-2 pcs</td><td>One per side are supported.</td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/80/ssd1306-oLED-lcd-display-0.91-inch-128x32-i2c-white" target="_blank" rel="noreferrer">OLED 0.91 module</a></td><td>0-2 pcs</td><td>It is possible to use only one display.</td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/114/sk6812-mini-e-rgb-smd-LED" target="_blank" rel="noreferrer">SK6812 Mini-E LEDs</a></td><td>60 pcs</td><td>RGB LEDs for the keycap backlight. <strong>Also the LEDs under the encoder must be soldered, because they are wired in series.</strong></td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/100/single-row-socket-headers-pins-mill-max-series-315" target="_blank" rel="noreferrer">Mill-Max Single Row Socket Headers</a>, or <a href="https://keycapsss.com/keyboard-parts/parts/91/spring-loaded-pin-headers-12-pin-2pcs-conthrough" target="_blank" rel="noreferrer">Spring-loaded pin headers</a>,</td><td>4 x 12 row headers</td><td>To make pro micro Hot-swappable. Highly recommended to get the header pins too (You can use diode legs if you don&#39;t get the header pins)</td><td></td></tr></tbody></table><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><strong>Note: please be careful, as the case will be scratched if it hits or rubs a hard thing after assembly.</strong></p><p>This PCB is reversible. We will mount parts <strong>on each side.</strong></p><p>Mark the surface with masking tape to make it easy to keep track of the back and front of each board.</p><p>The pictures in this guide show the PCB for the left side.</p><h2 id="attach-the-diodes" tabindex="-1">Attach the diodes <a class="header-anchor" href="#attach-the-diodes" aria-label="Permalink to &quot;Attach the diodes&quot;">​</a></h2><p>The diodes are mounted on the <strong>back side</strong> of the board.</p><p>Pay attention to orientation, diodes are polarized. If the orientation is incorrect, the key will not respond.</p><p>Solder the diode as shown in the following figure.</p><p><img src="'+p+'" alt="SMD Diode orientation" loading="lazy"></p><p>Apply preliminary solder (melt a small amount on the substrate/&quot;tin the pad&quot;) on one pad of the PCB diode.</p><p><img src="'+m+'" alt="SMD diode orientation" loading="lazy"><em>PCB back side (left half)</em></p><p>Then use tweezers to slide the diode into position, whilst you heat the pre-soldered pad. Remove the soldering iron and allow to cool, whilst still holding the diode.</p><p>Then solder the remaining side.<br> When all diodes have been soldered, check for missing spots.</p><p><img src="'+g+'" alt="Soldering diodes" loading="lazy"><em>PCB back side (left half)</em></p><p>You can use a multimeter in &quot;diode mode&quot;, on the front side of the board to ensure that the solder connections are good and that the orientation of the diodes is correct.</p><p><img src="'+u+'" alt="Soldering diodes" loading="lazy"><em>All diodes soldered on back side (left half)</em></p><h2 id="solder-the-leds-for-keycap-back-optionally" tabindex="-1">Solder the LEDs for keycap back (optionally) <a class="header-anchor" href="#solder-the-leds-for-keycap-back-optionally" aria-label="Permalink to &quot;Solder the LEDs for keycap back (optionally)&quot;">​</a></h2><p>Solder the SK6812 Mini-E LEDs (with legs), on the <strong>back side</strong> of the board.<br><strong>Pay attention to orientation of the LEDs</strong> (the angled leg of the led should be soldered to the pad of the PCB with the slanted white mark)<strong>.</strong></p><p>We solder LEDs using the same approach as for the diodes. Begin by pre-soldering one side of the LED pad.</p><p><img src="'+f+'" alt="SK6812 Mini-E soldering" loading="lazy"></p><p>Place the component, and hold it in place with tweezers.</p><p><img src="'+k+'" alt="SK6812 Mini-E soldering" loading="lazy"></p><p>Then solder the other pads.</p><p><img src="'+b+'" alt="SK6812 Mini-E soldering" loading="lazy"></p><p><strong>It is necessary to solder all LEDs, even if you use the rotary encoder.</strong></p><p>For the LEDs it&#39;s important to keep the heating as short as possible. Try to not touch the plastic of the LED itself with the iron but only the the metal legs. Use flux if you are having difficulty. The LEDs are connected in series. If a LED is broken or has bad solder connections, the following LEDs will either not light up at all or will light up in a different color than the default (red). Doublecheck the last LED that lights up properly and the first that doesn&#39;t.<br> On the LEDs with legs it&#39;s easily possible to get a loose connection.</p><h2 id="soldering-the-trrs-jack-and-reset-switch" tabindex="-1">Soldering the TRRS jack and reset switch <a class="header-anchor" href="#soldering-the-trrs-jack-and-reset-switch" aria-label="Permalink to &quot;Soldering the TRRS jack and reset switch&quot;">​</a></h2><p>The TRRS jack and the reset switch are mounted on the <strong>front side</strong> (opposite side of diodes). Attach the parts and fix them temporarily with masking tape. Turn over the board and solder the pins, making sure that the TRRS jack and reset switch are in firm contact with the board.</p><p><img src="'+y+'" alt="TRRS jack and reset button" loading="lazy"><em>PCB front side (left half)</em></p><p><strong>Be careful</strong> Double check your part orientation before you commit to soldering. A mistake here can mean painful desoldering experiences.</p><h2 id="attach-the-oled-socket" tabindex="-1">Attach the OLED socket <a class="header-anchor" href="#attach-the-oled-socket" aria-label="Permalink to &quot;Attach the OLED socket&quot;">​</a></h2><p>On the <strong>front side</strong> of the board, apply enough solder to bridge the four jumper terminals in the Pro Micro section.</p><p><img src="'+w+'" alt="Oled jumper pads" loading="lazy"><em>PCB front side (left half)</em></p><p>Attach the connector for the OLED on front side (opposite side of diodes). Be careful to avoid adding a lot of solder, as it is easy for solder to flow into the connector. Make sure it is straight and at a right-angle to the PCB.</p><h2 id="install-pro-micro-with-sockets" tabindex="-1">Install Pro Micro (with sockets) <a class="header-anchor" href="#install-pro-micro-with-sockets" aria-label="Permalink to &quot;Install Pro Micro (with sockets)&quot;">​</a></h2><h3 id="check-pro-micro-by-flashing" tabindex="-1">Check Pro Micro by flashing <a class="header-anchor" href="#check-pro-micro-by-flashing" aria-label="Permalink to &quot;Check Pro Micro by flashing&quot;">​</a></h3><p><strong>Before installing the Pro Micro, no matter which (can also happen on the Puchi-C), check whether they are working by plugging them in and <a href="#flash-keymap-on-pro-micropuchi-c">flashing the default keymap</a>.</strong></p><p>Open <a href="https://github.com/qmk/qmk_toolbox/releases/latest" target="_blank" rel="noreferrer">QMK Toolbox</a> and connect your Pro Micro/Puchi-C to the computer.<br> If your Pro Micro/Puchi-C is complete new (without a firmware on it), a message *&quot;**<em>Atmel DFU device connected: ...&quot;</em> should appear.</p><p>If the message does not appear, press the reset button on the Puchi-C, or short RST &amp; GND pins on the Pro Micro to bring it into the DFU mode. (For first timers you can short using a wire and touching an end each to RST &amp; GND pins while the pro micro is plugged in) If the message appears, the device should be working correctly.</p><p><img src="'+_+'" alt="QMK toolbox" loading="lazy"></p><h3 id="install-onto-pcb" tabindex="-1">Install onto PCB <a class="header-anchor" href="#install-onto-pcb" aria-label="Permalink to &quot;Install onto PCB&quot;">​</a></h3><p>You have 3 options:</p><ul><li>Use the pin headers enclosed in the bag of Pro Micro</li><li>Use Mill-Max sockets and Mill-Max headers</li><li>Use Mill-Max sockets with diode legs</li></ul><p>For other ways to mount your Pro Micros, look at <a href="https://nicedoc.io/foostan/crkbd/blob/master/corne-classic/doc/buildguide_en.md#using-pin-sockets" target="_blank" rel="noreferrer">the crkbd build guide.</a></p><h3 id="using-pin-header-enclosed" tabindex="-1">Using Pin header enclosed <a class="header-anchor" href="#using-pin-header-enclosed" aria-label="Permalink to &quot;Using Pin header enclosed&quot;">​</a></h3><p>The pin header enclosed in the bag of Pro Micro can be used. But I highly recommend using the Mill-Max socket headers, or Spring-loaded pin headers. With the Mill-Max header it&#39;s easier to replace the Pro Micro, if it&#39;s broken. (Especially the Pro Micros- the USB port will break at some point!)</p><p><img src="'+P+'" alt="Standard header/ Mill-Max socket header" loading="lazy"><em>Standard headers vs Mill-Max sockets. Note the standard header pins will NOT fit into the Mill-Max sockets. You have to get Mill-Max headers or use diode legs</em></p><ol><li>Note the <strong>outlined sets of holes in PCB,</strong> and insert the Standard header into the outlined holes on the <strong>front side</strong>. Please be careful, as the <strong>connections are different for the right and left boards.</strong> See the image in step 1 of <a href="#use-mill-max-sockets-and-mill-max-headers">Mill-Max section</a> for a reference.</li><li>Solder the Standard header from the <strong>back side</strong> and pay attention to not creating solder bridges between the different sets of holes.</li><li>Place the Pro Micro/Puchi-C on top of the headers on the <strong>Front side</strong>. <strong>(USB socket facing down)</strong>. <img src="'+t+'" alt="Mill-Max sockets" loading="lazy"></li><li>Solder the Pro-Micro in place</li></ol><p>Go to <a href="#install-the-oled-sd1306-on-the-socket">Install the OLED on the socket</a></p><h3 id="use-mill-max-sockets-and-mill-max-headers" tabindex="-1">Use Mill-Max sockets and Mill-Max headers <a class="header-anchor" href="#use-mill-max-sockets-and-mill-max-headers" aria-label="Permalink to &quot;Use Mill-Max sockets and Mill-Max headers&quot;">​</a></h3><ol><li>Note the <strong>outlined sets of holes in PCB,</strong> and insert the Mill-Max sockets into the outlined holes on the <strong>front side</strong>. Please be careful, as the <strong>connections are different for the right and left boards.</strong><img src="'+o+'" alt="Pro Micro_PCB" loading="lazy"><em>PCB front side (left half)</em></li><li>Solder the Mill-Max sockets from the <strong>back side</strong> and pay attention to not creating solder bridges between the different sets of holes.</li><li>Insert the Mill-Max pins with pliers into the sockets. <img src="'+q+'" alt="Mill-Max sockets" loading="lazy"><em>Example image with Mill-Max sockets</em></li><li>Place the Pro Micro/Puchi-C on top of the headers on the <strong>Front side</strong>. <strong>(USB socket facing down)</strong>. <img src="'+t+'" alt="Punchi-C Placement" loading="lazy"><em>Puchi-C Placement</em></li><li>Solder the pins.</li></ol><p>Go to <a href="#install-the-oled-sd1306-on-the-socket">Install the OLED on the socket</a></p><h3 id="use-mill-max-sockets-with-diode-legs" tabindex="-1">Use Mill-Max sockets with diode legs <a class="header-anchor" href="#use-mill-max-sockets-with-diode-legs" aria-label="Permalink to &quot;Use Mill-Max sockets with diode legs&quot;">​</a></h3><ol><li>Note the <strong>outlined sets of holes in PCB,</strong> and insert the Mill-Max sockets into the outlined holes on the <strong>front side</strong>. Please be careful, as the <strong>connections are different for the right and left boards.</strong><img src="'+o+'" alt="Pro Micro_PCB" loading="lazy"><em>PCB front side (left half)</em></li><li>Solder the Mill-Max sockets from the <strong>back side</strong> and pay attention to not creating solder bridges between the different sets of holes.</li><li>Optional but highly recommended: Cover the sockets with heat resistant tape (scotch tape or electrical tape). This will prevent the solder seeping into the sockets which will make it practically impossible to remove the pro-microsocket <img src="'+M+'" alt="Pro Micro with tape" loading="lazy"><em>Example with tape</em></li><li>Insert the diodes legs with pliers or tweezers into the sockets. You should hear/feel 2 &#39;clicks&#39; Once when it puches through the tape and the second when it engages into place on the Max-Mill socket. Do not use your hands as the diode legs can be sharp <img src="'+x+'" alt="Mill-Max sockets" loading="lazy"><em>Example image with diode legs</em></li><li>Place the Pro Micro/Puchi-C <strong>(USB socket facing down)</strong>. <img src="'+S+'" alt="Diode legs 1" loading="lazy"><em>Pro Micro placement with diode legs</em></li><li>Solder the pins. Shorten the pins with side cutters/flush cutters <img src="'+C+'" alt="Diode legs 2" loading="lazy"><em>Time to snip</em></li><li>You should be able to slowly wedge off the pro micro from the Max-Mill sockets using tweezers and a bit of levering from the top and bottom of the pro micro. Take off the tape. <img src="'+v+'" alt="Pro Micro Removed" loading="lazy"><em>Pro Micro levered off the pins. Now time to remove tape</em></li></ol><h2 id="install-the-oled-sd1306-on-the-socket" tabindex="-1">Install the OLED (SD1306) on the socket <a class="header-anchor" href="#install-the-oled-sd1306-on-the-socket" aria-label="Permalink to &quot;Install the OLED (SD1306) on the socket&quot;">​</a></h2><p>Remove the black plastic spacer that&#39;s part of the header installed in the OLED. Then you&#39;ll be able to shorten it&#39;s legs with your pliers and put them into the socket, resulting into a way more low profile OLED. You can wiggle it off with pliers carefully.</p><p><img src="'+T+'" alt="Oled SD1306 shorten pins" loading="lazy"> <img src="'+B+'" alt="Oled SD1306 shorten pins" loading="lazy"></p><h2 id="you-have-reached-a-checkpoint" tabindex="-1">You have reached a checkpoint <a class="header-anchor" href="#you-have-reached-a-checkpoint" aria-label="Permalink to &quot;You have reached a checkpoint&quot;">​</a></h2><p>Plug your keyboard (<strong>do not plug-in or remove the TRRS cable, while a Pro Micro is connected via USB</strong>), look what happens, solve problems, be happy if there are none (if you followed all the steps your pro micros should have <a href="#flash-keymap-on-pro-micropuchi-c">firmware</a> at this point).</p><p>By now you can also checked whether all switches will be able to work. In order to do so, open the <a href="https://config.qmk.fm/#/test" target="_blank" rel="noreferrer">QMK Test Site</a>, short the pads on which the kailh sockets will be installed (next step) with tweezers.</p><p>See <a href="#troubleshooting">Troubleshooting</a> if anything is not working</p><p><img src="'+D+'" alt="Tweezers test switch" loading="lazy"></p><h2 id="solder-the-sockets" tabindex="-1">Solder the sockets <a class="header-anchor" href="#solder-the-sockets" aria-label="Permalink to &quot;Solder the sockets&quot;">​</a></h2><p>The sockets are mounted on the <strong>back side</strong>, the same side as the diodes.</p><p>Much like the approach used for the diodes above, begin by pre-soldering one side of the socket pad.</p><p><img src="'+j+'" alt="Solder Kailh Hotswap sockets" loading="lazy"></p><p>Place the component, and hold it in place with tweezers. (The sockets can also be held in place by hand, but please take extra care not to burn yourself.)</p><p><img src="'+z+'" alt="Solder Kailh Hotswap sockets" loading="lazy"></p><blockquote><p>The sockets take <strong>way</strong> more solder than the other components like the LEDs and the diodes. But don&#39;t exaggerate...</p></blockquote><h2 id="case-assembly" tabindex="-1">Case assembly <a class="header-anchor" href="#case-assembly" aria-label="Permalink to &quot;Case assembly&quot;">​</a></h2><p><img src="'+R+'" alt="case parts overview" loading="lazy"></p><h3 id="attach-the-spacer" tabindex="-1">Attach the spacer <a class="header-anchor" href="#attach-the-spacer" aria-label="Permalink to &quot;Attach the spacer&quot;">​</a></h3><p>Attach two <strong>10mm spacers</strong> to the holes near TRRS jack with the <strong>5mm screws</strong>. It&#39;s easy to insert a screw from the back of the board and attach the spacer from the top.</p><p><img src="'+E+'" alt="Spacer for oled guard plate" loading="lazy"></p><p>Attach the <strong>7mm spacer</strong> to the top plate. If your kit comes with washers attached those to the spacers (They will hold the top plate slightly off the PCB)</p><p><img src="'+I+'" alt="Top plate 7mm spacer" loading="lazy"></p><p><img src="'+L+'" alt="Top plate washer" loading="lazy"><em>Spacer washer for acrylic case (not necessary for FR4 plate case).</em></p><h3 id="prepare-the-rotary-encoder" tabindex="-1">Prepare the rotary encoder <a class="header-anchor" href="#prepare-the-rotary-encoder" aria-label="Permalink to &quot;Prepare the rotary encoder&quot;">​</a></h3><p>Remove the alignment legs on the rotary encoder with diagonal pliers.</p><p><img src="'+A+'" alt="Rotary encoder cut legs" loading="lazy"></p><p>If your rotary encoder has a metal surface at the bottom, cover it with some isolation tape, to prevent shorts on the LED pads.</p><p><img src="'+O+'" alt="Rotary encoder isolation tape" loading="lazy"></p><p>You can place one encoder per side, or leave it empty and place a switch at this position.</p><p><img src="'+K+'" alt="Rotary encoder position" loading="lazy"></p><p><strong>Do not solder the rotary encoder at this point.</strong> If it sits loose on the mid pcb, the clearance helps that the encoder fits in the top plate hole.</p><p><img src="'+U+'" alt="Rotary encoder positions" loading="lazy"></p><h3 id="attach-the-key-switch" tabindex="-1">Attach the key switch <a class="header-anchor" href="#attach-the-key-switch" aria-label="Permalink to &quot;Attach the key switch&quot;">​</a></h3><p>Attach four key switches to the top plate. The hole for the switch led is facing down.</p><p><img src="'+Q+'" alt="Top plate with 4 switches" loading="lazy"></p><p>It&#39;s important that the switch pins are not bend.</p><p><img src="'+F+'" alt="Switch pin align" loading="lazy"></p><p>Insert the switch into the board for alignment, and line up the components.</p><p><img src="'+G+'" alt="Top plate" loading="lazy"><img src="'+H+'" alt="Top plate align" loading="lazy"></p><p>After confirming that there are no bends in the switch pins, you can attach it firmly by starting from the middle row and working outward. Be careful: some switches require some power for installation. Always be careful to put the switches in nice and straight, otherwise you&#39;ll bend the pins and scratch the PCB. After mounting the plate, push the switches again to make sure that installation is complete.</p><p><img src="'+Y+'" alt="Top plate complete with switches" loading="lazy"></p><p>Confirm that the rotary encoder sits straight on the PCB.<br> Solder the 5 points.</p><p><img src="'+N+'" alt="Solder the rotary encoder" loading="lazy"></p><p>Soldering the rotary encoder is as simple as any other component. Put the encoder from the front into the holes on the PCB, just below the screen, and solder it from the back.</p><p><strong>Tip</strong> Depending on your case you should first try and bend the rotary encoder legs a bit before soldering it in. The legs can prevent your case from closing completly, as it will rest on the protruding legs. Bending the pins so that they are flush with the encoder helps here. (you can also just clip them off)</p><blockquote><p><strong>For your information.</strong> The top <strong>two</strong> legs serve as a simple connection that is closed by the rotary encoders tactile press. It&#39;s connected to the pins a switch would be connected to, if there were on in the place of the rotary encoder. Therefore, in your firmware the rotary encoder will behave as a normal keyswitch in the matrix.</p></blockquote><p>The lower three pins do the actual rotary-encoding part</p><h3 id="pro-micro-protective-acrylic-installation" tabindex="-1">Pro Micro protective acrylic installation <a class="header-anchor" href="#pro-micro-protective-acrylic-installation" aria-label="Permalink to &quot;Pro Micro protective acrylic installation&quot;">​</a></h3><p>Peel off the protective plastic layer covering the acrylic.<br> Antistatic spray helps to counteract that the cover is a dust magnet. I use <a href="https://amzn.to/2ZMTz93" target="_blank" rel="noreferrer">Velind Antistatik Spray</a>*<em>affiliate link</em></p><p><img src="'+Z+'" alt="Guard plate protective film" loading="lazy"></p><p>Attach the acrylic plate to the board with 5mm screws.</p><p><img src="'+V+'" alt="Guard plate" loading="lazy"><img src="'+W+'" alt="Guard plate" loading="lazy"></p><h3 id="assemble-the-bottom-plate" tabindex="-1">Assemble the bottom plate <a class="header-anchor" href="#assemble-the-bottom-plate" aria-label="Permalink to &quot;Assemble the bottom plate&quot;">​</a></h3><p>To complete the case, attach the bottom plate with 5 screws and stick the 4 rubber feeds to the corners.</p><p><img src="'+X+'" alt="Bottom plate" loading="lazy"></p><p>Your Kimiko keyboard is now complete.</p><p><img src="https://media.giphy.com/media/PudZiAbQDUEik/giphy.gif" alt="Proud" loading="lazy"></p><h2 id="flash-keymap-on-pro-micro-puchi-c" tabindex="-1">Flash keymap on Pro Micro/Puchi-C <a class="header-anchor" href="#flash-keymap-on-pro-micro-puchi-c" aria-label="Permalink to &quot;Flash keymap on Pro Micro/Puchi-C&quot;">​</a></h2><p>The board requires a <a href="https://github.com/qmk/qmk_firmware/tree/master/keyboards/keycapsss/kimiko" target="_blank" rel="noreferrer">keymap</a> in order to function. This section assumes that you&#39;re familiar with keymaps and the use of the QMK tool. If not, please refer to <a href="https://docs.qmk.fm/#/getting_started_build_tools" target="_blank" rel="noreferrer">the QMK &quot;Getting Started&quot; guide</a> (Windows: MSYS2; Mac, Linux: avrdude)</p><p>The <a href="https://github.com/qmk/qmk_toolbox/releases" target="_blank" rel="noreferrer">QMK Toolbox</a> can be used to write non-customized keymaps via a GUI, avoiding the need to configure a local QMK environment. (For custom keymaps/rotary encoder behavior, it&#39;s recommended to build the full environment described above).</p><p>Clone/download the QMK firmware and execute the following in the <a href="https://github.com/qmk/qmk_firmware" target="_blank" rel="noreferrer">qmk_firmware</a> directory to write the default Lily58L keymap</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/kimiko:default:avrdude</span></span></code></pre></div><p>When <strong><code>Detecting USB port, reset your controller now...</code></strong> is displayed, press the reset button on the keyboard to start writing. Each half of the keyboard must be programmed separately using this approach.</p><p>If you&#39;re using DFU bootloader (in case of the Puchi-C/Elite-C), replace the <code>avrdude</code> with <code>dfu</code>.</p><h3 id="congratulations-🥳" tabindex="-1">Congratulations 🥳 <a class="header-anchor" href="#congratulations-🥳" aria-label="Permalink to &quot;Congratulations 🥳&quot;">​</a></h3><p>If everything works: You have built your Kimiko. Have fun! <a href="#troubleshooting">If something doesn&#39;t work</a></p><h2 id="customize-the-default-keymap" tabindex="-1">Customize the default keymap <a class="header-anchor" href="#customize-the-default-keymap" aria-label="Permalink to &quot;Customize the default keymap&quot;">​</a></h2><p><strong><a href="./Keymap.html">Keymap-Guide</a></strong></p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="q-one-or-more-rows-columns-of-key-switches-do-not-respond" tabindex="-1">Q. One or more rows/columns of key switches do not respond <a class="header-anchor" href="#q-one-or-more-rows-columns-of-key-switches-do-not-respond" aria-label="Permalink to &quot;Q. One or more rows/columns of key switches do not respond&quot;">​</a></h3><p>A. The Pro Micro board may not be soldered and attached firmly. Check again, and re-solder and reinstall if necessary.</p><h3 id="q-a-single-key-switch-doesn-t-respond" tabindex="-1">Q. A single key switch doesn&#39;t respond <a class="header-anchor" href="#q-a-single-key-switch-doesn-t-respond" aria-label="Permalink to &quot;Q. A single key switch doesn&#39;t respond&quot;">​</a></h3><p>A. There may be a problem with the key switch&#39;s insertion, socket or diode soldering.</p><p>In the case of bad key switch insertion: After removing the key switch, make sure that the pins aren&#39;t bent, and then push it in again and install it.</p><p>In the case of badly attached socket: Re-solder the problem socket, or reflow and add solder if the joint is weak.</p><p>In the case of badly attached diode: Check the <a href="#attach-the-diodes">direction of the diode</a> in question. If it is wrong, remove it and re-solder it. Additionally, if there isn&#39;t enough solder, please re-solder.</p><h3 id="q-both-half-s-are-working-as-single-but-if-i-connect-them-via-trrs-cable-one-side-is-not-working" tabindex="-1">Q. Both half&#39;s are working as single, but if i connect them via TRRS cable one side is not working <a class="header-anchor" href="#q-both-half-s-are-working-as-single-but-if-i-connect-them-via-trrs-cable-one-side-is-not-working" aria-label="Permalink to &quot;Q. Both half&#39;s are working as single, but if i connect them via TRRS cable one side is not working&quot;">​</a></h3><p>A. Check the TRRS jack solder points for bridges or cold solder points.</p><p>The TRRS cable should have 4 poles.</p><p>Use a multimeter to check the cable. Each pole should only have connection to the opposite pole.</p><h3 id="q-one-side-does-not-respond" tabindex="-1">Q. One side does not respond <a class="header-anchor" href="#q-one-side-does-not-respond" aria-label="Permalink to &quot;Q. One side does not respond&quot;">​</a></h3><p>A. Check if all LED‘s have the correct orientation.</p><h3 id="q-a-symbol-different-from-the-symbol-input-by-or-etc-is-input-on-windows-etc" tabindex="-1">Q. A symbol different from the symbol input by &quot;@&quot; or &quot;[&quot; etc. is input (on Windows, etc.) <a class="header-anchor" href="#q-a-symbol-different-from-the-symbol-input-by-or-etc-is-input-on-windows-etc" aria-label="Permalink to &quot;Q. A symbol different from the symbol input by &quot;@&quot; or &quot;[&quot; etc. is input (on Windows, etc.)&quot;">​</a></h3><p>A. Please set OS Keyboard Layout as a US keyboard in the OS keyboard settings.</p><p><strong>If you have any problems, please feel free to send a message on Discord (<a href="https://discord.gg/frjFXZB" target="_blank" rel="noreferrer">https://discord.gg/frjFXZB</a>) or Twitter: <a href="https://twitter.com/keycapsss" target="_blank" rel="noreferrer">@keycapsss</a></strong></p>',156)])])}const ne=a(J,[["render",$]]);export{ie as __pageData,ne as default};
